window.__votdWeek && window.__votdWeek({"week":"2029-01-01","reading":"","days":[{"d":"2029-01-01","ref":"Joseph Smith—History 1:17","b":"JS—History","c":1,"v":17,"he":"אַךְ הוֹפִיעַ וּכְבָר מָצָאתִי אֶת־עַצְמִי מֻצָּל מִן הָאוֹיֵב שֶׁאָסַר אוֹתִי וְהָאוֹר נָח עָלַי רָאִיתִי שְׁנֵי אֲנָשִׁים זָהֳרָם וּכְבוֹדָם אֵין לְתָאֵר עוֹמְדִים מֵעָלַי בָּאֲוִיר אֶחָד מֵהֶם דִּבֶּר אֵלַי קוֹרֵא בִּשְׁמִי וְאָמַר בְּהַצְבִּיעוֹ אֶל הַשֵּׁנִי זֶה בְּנִי אֲהוּבִי שְׁמַע לוֹ׃","en":"It no sooner appeared than I found myself delivered from the enemy which held me bound. When the light rested upon me I saw two Personages, whose brightness and glory defy all description, standing above me in the air. One of them spake unto me, calling me by name and said, pointing to the other—This is My Beloved Son. Hear Him!"},{"d":"2029-01-02","ref":"D&C 1:30","b":"D&C","c":1,"v":30,"he":"וְגַם אֲשֶׁר נִתְּנוּ לָהֶם הַמִּצְוֹת הָאֵלֶּה יִהְיֶה לָהֶם כֹּחַ לְיַסֵּד אֶת־הַכְּנֵסִיָּה הַזֹּאת וּלְהוֹצִיאָהּ מֵאֹפֶל וּמֵחֹשֶׁךְ הַכְּנֵסִיָּה הָאֲמִתִּית וְהַחַיָּה לְבַדָּהּ עַל־פְּנֵי כׇל־הָאָרֶץ אֲשֶׁר בָּהּ חָפַצְתִּי אֲנִי יְהוָה מְדַבֵּר אֶל־הַכְּנֵסִיָּה כֻּלָּהּ וְלֹא אֶל־אִישׁ לְבַדּוֹ׃","en":"And also those to whom these commandments were given, might have power to lay the foundation of this church, and to bring it forth out of obscurity and out of darkness, the only true and living church upon the face of the whole earth, with which I, the Lord, am well pleased, speaking unto the church collectively and not individually—"},{"d":"2029-01-03","ref":"D&C 1:38","b":"D&C","c":1,"v":38,"he":"אֲשֶׁר דִּבַּרְתִּי אֲנִי יְהוָה דִּבַּרְתִּי וְלֹא אָשׁוּב מִדְּבָרִי וְאִם יַעַבְרוּ הַשָּׁמַיִם וְהָאָרֶץ דְּבָרִי לֹא יַעֲבֹר כִּי יִמָּלֵא הַכֹּל אִם בְּקוֹלִי אִם בְּקוֹל עֲבָדַי אֶחָד הוּא׃","en":"What I the Lord have spoken, I have spoken, and I excuse not myself; and though the heavens and the earth pass away, my word shall not pass away, but shall all be fulfilled, whether by mine own voice or by the voice of my servants, it is the same."},{"d":"2029-01-04","ref":"D&C 13:1","b":"D&C","c":13,"v":1,"he":"עֲלֵיכֶם חֲבֵרַי הָעֲבָדִים בְּשֵׁם הַמָּשִׁיחַ אֲנִי נֹתֵן כְּהֻנַּת אַהֲרֹן אֲשֶׁר בְּיָדָהּ מַפְתְּחוֹת שָׁרֵת הַמַּלְאָכִים וּבְשׂוֹרַת הַתְּשׁוּבָה וּטְבִילָה בַּמַּיִם לִסְלִיחַת חֲטָאִים וְזֹאת לֹא תִלָּקַח עוֹד מִן הָאָרֶץ עַד אֲשֶׁר יַגִּישׁוּ בְּנֵי לֵוִי עוֹד מִנְחָה לַיהוָה בִּצְדָקָה׃","en":"Upon you my fellow servants, in the name of Messiah I confer the Priesthood of Aaron, which holds the keys of the ministering of angels, and of the gospel of repentance, and of baptism by immersion for the remission of sins; and this shall never be taken again from the earth, until the sons of Levi do offer again an offering unto the Lord in righteousness."},{"d":"2029-01-05","ref":"D&C 76:22","b":"D&C","c":76,"v":22,"he":"וְעַתָּה אַחֲרֵי עֵדֻיּוֹת רַבּוֹת אֲשֶׁר נִתְּנוּ עָלָיו זֹאת הָעֵדוּת הָאַחֲרוֹנָה אֲשֶׁר אֲנַחְנוּ מְעִידִים עָלָיו כִּי הוּא חָי׃","en":"And now, after the many testimonies which have been given of him, this is the testimony, last of all, which we give of him: That he lives!"},{"d":"2029-01-06","ref":"D&C 76:24","b":"D&C","c":76,"v":24,"he":"כִּי עַל יָדוֹ וּבְיָדוֹ וּמִמֶּנּוּ הָעוֹלָמוֹת נִבְרָאִים וְיוֹשְׁבֵיהֶם הֵם נוֹלָדִים בָּנִים וּבָנוֹת לֵאלֹהִים׃","en":"That by him, and through him, and of him, the worlds are and were created, and the inhabitants thereof are begotten sons and daughters unto God."},{"d":"2029-01-07","ref":"D&C 135:3","b":"D&C","c":135,"v":3,"he":"יוֹסֵף סְמִית נְבִיא יְהוָה וְחֹזֵהוּ עָשָׂה יוֹתֵר לְבַד מִיֵּשׁוּעַ לִישׁוּעַת בְּנֵי אָדָם בָּעוֹלָם הַזֶּה מִכׇּל אָדָם אֲשֶׁר חַי בּוֹ מֵעוֹלָם בְּעֶשְׂרִים שָׁנָה קְצָרוֹת הוֹצִיא אֶת־סֵפֶר מוֹרְמוֹן אֲשֶׁר תִּרְגֵּם בְּמַתְּנַת אֱלֹהִים וּבְכֹחוֹ וּבְיָדוֹ הוֹצִיאוֹ בִּשְׁתֵּי יַבָּשׁוֹת שָׁלַח אֶת־מְלֹא בְּשׂוֹרַת עוֹלָם אֲשֶׁר בּוֹ לְאַרְבַּע כַּנְפוֹת הָאָרֶץ הוֹצִיא אֶת־הַחֲזוֹנוֹת וְהַמִּצְווֹת אֲשֶׁר מֵהֶם אֶת־סֵפֶר הַלֶּקַח וְהַבְּרִיתוֹת הַזֶּה וְעוֹד כִּתְבֵי חׇכְמָה רַבִּים וְהוֹרָאוֹת לְטוֹבַת בְּנֵי הָאָדָם קִבֵּץ אֲלָפִים רַבִּים מִקְּדוֹשֵׁי אַחֲרִית הַיָּמִים יָסַד עִיר גְּדוֹלָה וְהִנִּיחַ תְּהִלָּה וְשֵׁם אֲשֶׁר לֹא יוּמְתוּ חָיָה גָּדוֹל וּמֵת גָּדוֹל בְּעֵינֵי אֱלֹהִים וְעַמּוֹ וּכְרֹב מְשִׁיחֵי יְהוָה בִּימֵי קֶדֶם חָתַם אֶת־שְׁלִיחוּתוֹ וְאֶת מַעֲשָׂיו בְּדָמוֹ וְכֵן גַּם אָחִיו חִירָם בְּחַיֵּיהֶם לֹא נֶחְלָקוּ וּבְמוֹתָם לֹא נִפְרָדוּ׃","en":"Joseph Smith, the Prophet and Seer of the Lord, has done more, save Jesus only, for the salvation of men in this world, than any other man that ever lived in it. In the short space of twenty years, he has brought forth the Book of Mormon, which he translated by the gift and power of God, and has been the means of publishing it on two continents; has sent the fulness of the everlasting gospel, which it contained, to the four quarters of the earth; has brought forth the revelations and commandments which compose this book of Doctrine and Covenants, and many other wise documents and instructions for the benefit of the children of men; gathered many thousands of the Latter-day Saints, founded a great city, and left a fame and name that cannot be slain. He lived great, and he died great in the eyes of God and his people; and like most of the Lord's anointed in ancient times, has sealed his mission and his works with his own blood; and so has his brother Hyrum. In life they were not divided, and in death they were not separated!"}]});
